# Count blocks connected by overlap; selected may be those making shape whose top-left coords are in a certain relation.
# In demos, outputs show recolor portions of same-color components that are specifically 2x2 squares participating in a 2x2 pattern? Let's map occupied cells for demos, connected components.
from collections import deque
D=[(0,0),(0,11),(1,4),(2,7),(3,1),(3,13),(4,10),(5,6),(5,15)]
for x in [D]:
 cells={(r+i,c+j) for r,c in x for i in range(2) for j in range(2)}
 seen=set(); comps=[]
 while cells-seen:
  st=[next(iter(cells-seen))]; comp=set(st);seen|=comp
  while st:
   r,c=st.pop()
   for q in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
    if q in cells and q not in seen:seen.add(q);comp.add(q);st.append(q)
  comps.append(comp)
 print([len(c) for c in comps])
